def move_single_conditions(apps, schema_editor):
    """Satu kondisi lama -> grup 1 WHEN; histeresis lama -> grup 1 CLEAR (variabel sama)."""
    EcaSpec = apps.get_model("rules", "EcaSpec")
    EcaCondition = apps.get_model("rules", "EcaCondition")
    for spec in EcaSpec.objects.exclude(variable=None):
        if spec.operator and spec.threshold is not None:
            EcaCondition.objects.create(
                spec=spec, role="WHEN", group=1, order=0,
                variable_id=spec.variable_id, operator=spec.operator, threshold=spec.threshold,
            )
        if spec.clear_operator and spec.clear_threshold is not None:
            EcaCondition.objects.create(
                spec=spec, role="CLEAR", group=1, order=0,
                variable_id=spec.variable_id, operator=spec.clear_operator, threshold=spec.clear_threshold,
            )


